class Solution {
public:
    int longestSquareStreak(vector<int>& nums) {
        unordered_set<int> s(nums.begin(), nums.end());
        unordered_map<int,int> memo;
        int best = 0;
        for (int x : nums) {
            best = max(best, dfs(x, s, memo));
        }
        return best >= 2 ? best : -1;
    }
private:
    int dfs(long long x, unordered_set<int>& s, unordered_map<int,int>& memo) {
        if (x > 100000) return 0;
        int key = (int)x;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        long long sq = x * x;
        int res = 1;
        if (sq <= 100000 && s.count((int)sq)) {
            res = 1 + dfs(sq, s, memo);
        }
        memo[key] = res;
        return res;
    }
};
